const SB = 'https://wdjlellvhvsarivdpgou.supabase.co';
const entrada = $('Webhook').first().json;
const ANON = String((entrada.headers || {}).apikey || '');
const jwt = String((entrada.headers || {})['author' + 'ization'] || '').split(' ').pop();
const avaliacaoId = (entrada.body || {}).avaliacao_id;
if (!jwt || !/^[0-9a-f-]{36}$/i.test(String(avaliacaoId || ''))) throw new Error('Pedido inválido.');
const H = Object.fromEntries([['api' + 'key', ANON], ['Author' + 'ization', 'Bea' + 'rer ' + jwt]]);
const req = (o) => this.helpers.httpRequest({ json: true, ...o, headers: { ...H, ...(o.headers || {}) } });
const patch = (campos) => req({ method: 'PATCH', url: SB + '/rest/v1/avaliacoes_imoveis?id=eq.' + avaliacaoId, body: { ...campos, etapa_atualizada_em: new Date().toISOString() }, headers: { Prefer: 'return=minimal' } });
const progresso = async (texto, tipo, zerar) => { try { const [r] = await req({ method: 'GET', url: SB + '/rest/v1/avaliacoes_imoveis?id=eq.' + avaliacaoId + '&select=progresso' }); const atual = zerar ? (r.progresso || []).filter(p => p.tipo !== tipo) : (r.progresso || []); await req({ method: 'PATCH', url: SB + '/rest/v1/avaliacoes_imoveis?id=eq.' + avaliacaoId, body: { progresso: [...atual, { em: new Date().toISOString(), texto, tipo }] }, headers: { Prefer: 'return=minimal' } }); } catch (e) { /* progresso é só informativo */ } };

try {
  const [av] = await req({ method: 'GET', url: SB + '/rest/v1/avaliacoes_imoveis?id=eq.' + avaliacaoId + '&select=id,endereco,condominio,bairro,cidade,uf,cep,tipo_imovel,ano_construcao,fontes_dados' });
  if (!av) throw new Error('Avaliação não encontrada ou sem acesso.');
  await progresso('Localizando o endereço no Google…', 'dados', true);
  const endereco = [String(av.endereco || '').split(',').slice(0, 2).join(','), av.bairro, av.cidade, av.uf, av.cep, 'Brasil'].filter(Boolean).join(', ');
  return [{ json: { av, endereco } }];
} catch (e) {
  await patch({ etapa: 'conferir_dados', etapa_erro: null }).catch(() => {});
  throw e;
}

