const { av, endereco } = $('Ler avaliação').first().json;
const g = $input.first().json || {};
const r = (g.results || [])[0];
const comp = (tipo) => { const c = ((r && r.address_components) || []).find(x => (x.types || []).includes(tipo)); return c ? c.long_name : null; };
const google = r ? { endereco_google: r.formatted_address, bairro: comp('sublocality_level_1') || comp('sublocality'), cidade: comp('administrative_area_level_2'), uf: ((r.address_components || []).find(x => (x.types || []).includes('administrative_area_level_1')) || {}).short_name || null, cep: (comp('postal_code') || '').replace(/[^0-9]/g, '') || null, numero: comp('street_number'), lat: r.geometry.location.lat, lng: r.geometry.location.lng, precisao: r.geometry.location_type } : null;
await progresso(google ? 'Endereço localizado: ' + google.endereco_google : 'Não achamos o endereço exato no Google; seguimos com o que temos', 'dados');
await progresso('Pesquisando na internet o nome do prédio e o ano de construção…', 'dados');
const campo = (t) => ({ type: 'object', additionalProperties: false, required: ['valor', 'url'], properties: { valor: { type: t }, url: { type: 'string' } } });
const schema = { type: 'object', additionalProperties: false, required: ['condominio', 'ano_construcao', 'andares', 'observacao'], properties: { condominio: campo('string'), ano_construcao: campo('integer'), andares: campo('integer'), observacao: { type: 'string' } } };
const sistema = 'Você pesquisa dados públicos de um imóvel no Brasil para um laudo de avaliação. Pesquise o endereço informado e responda só com o que encontrar em fontes confiáveis (sites de condomínios, portais imobiliários, construtoras). ' +
  'condominio: nome do edifício ou condomínio NESSE número da rua (texto vazio se não for prédio/condomínio ou se não tiver certeza). ano_construcao: ano em que o prédio foi construído/entregue (0 se não souber). andares: número de andares do prédio (0 se não souber). ' +
  'Em cada campo, url = página onde você viu a informação (texto vazio se não achou). Não invente; na dúvida deixe vazio ou 0. observacao: 1 frase curta.';
const pergunta = 'Endereço: ' + (google ? google.endereco_google : endereco) + '. Tipo: ' + (av.tipo_imovel || 'imóvel') + (av.condominio ? '. Nome informado: ' + av.condominio : '') + '. Qual o nome do prédio/condomínio, o ano de construção e o número de andares?';
return [{ json: { av, google, req: { model: 'anthropic/claude-sonnet-5.5', temperature: 0, usage: { include: true }, plugins: [ { id: 'web', max_results: 10 } ], response_format: { type: 'json_schema', json_schema: { name: 'predio', strict: true, schema } }, messages: [ { role: 'system', content: sistema }, { role: 'user', content: pergunta } ] } } }];

