const entrada = $('Webhook').first().json;
const ANON = String((entrada.headers || {}).apikey || '');
const jwt = String((entrada.headers || {})['author' + 'ization'] || '').split(' ').pop();
const avaliacaoId = (entrada.body || {}).avaliacao_id;
if (!jwt || !/^[0-9a-f-]{36}$/i.test(String(avaliacaoId || ''))) throw new Error('Pedido inválido.');
const H = Object.fromEntries([['api' + 'key', ANON], ['Author' + 'ization', 'Bea' + 'rer ' + jwt]]);
const req = (o) => this.helpers.httpRequest({ json: true, ...o, headers: { ...H, ...(o.headers || {}) } });
const patch = (campos) => req({ method: 'PATCH', url: SB + '/rest/v1/avaliacoes_imoveis?id=eq.' + avaliacaoId, body: { ...campos, etapa_atualizada_em: new Date().toISOString() }, headers: { Prefer: 'return=minimal' } });
const progresso = async (texto, tipo, zerar) => { try { const [r] = await req({ method: 'GET', url: SB + '/rest/v1/avaliacoes_imoveis?id=eq.' + avaliacaoId + '&select=progresso' }); const atual = zerar ? (r.progresso || []).filter(p => p.tipo !== tipo) : (r.progresso || []); await req({ method: 'PATCH', url: SB + '/rest/v1/avaliacoes_imoveis?id=eq.' + avaliacaoId, body: { progresso: [...atual, { em: new Date().toISOString(), texto, tipo }] }, headers: { Prefer: 'return=minimal' } }); } catch (e) { /* progresso é só informativo */ } };

try {
  const { av, google } = $('Montar pesquisa do prédio').first().json;
  const r = $input.first().json || {};
  let d = null; try { d = JSON.parse(r.choices[0].message.content); } catch (e) { d = null; }
  const fontes = { ...(av.fontes_dados || {}) };
  const campos = {};
  // Só preenche o que está vazio: nunca sobrescreve o que veio do documento ou foi digitado.
  if (google) {
    if (!av.bairro && google.bairro) { campos.bairro = google.bairro; fontes.bairro = { fonte: 'Google' }; }
    if (!av.cep && google.cep && google.cep.length === 8) { campos.cep = google.cep; fontes.cep = { fonte: 'Google' }; }
    if (!av.cidade && google.cidade) { campos.cidade = google.cidade; fontes.cidade = { fonte: 'Google' }; }
    if (!av.uf && google.uf) { campos.uf = google.uf; fontes.uf = { fonte: 'Google' }; }
    fontes.localizacao = { fonte: 'Google', endereco: google.endereco_google, lat: google.lat, lng: google.lng, precisao: google.precisao };
  }
  const achou = [];
  if (d) {
    const ano = Number(d.ano_construcao && d.ano_construcao.valor);
    if (!av.condominio && d.condominio && String(d.condominio.valor || '').trim()) { campos.condominio = String(d.condominio.valor).trim().slice(0, 120); fontes.condominio = { fonte: 'busca na web', url: d.condominio.url || null }; achou.push('prédio ' + campos.condominio); }
    if (!av.ano_construcao && ano >= 1850 && ano <= new Date().getFullYear()) { campos.ano_construcao = ano; fontes.ano_construcao = { fonte: 'busca na web', url: d.ano_construcao.url || null }; achou.push('construído em ' + ano); }
    if (Number(d.andares && d.andares.valor) > 0) { fontes.andares = { valor: Number(d.andares.valor), fonte: 'busca na web', url: d.andares.url || null }; achou.push(d.andares.valor + ' andares'); }
  }
  await progresso(achou.length ? 'Encontramos: ' + achou.join(', ') : 'Não encontramos dados do prédio na internet; confira os campos', 'dados');
  await patch({ ...campos, fontes_dados: fontes, etapa: 'conferir_dados', etapa_erro: null });
  return [{ json: { ok: true, preenchidos: Object.keys(campos) } }];
} catch (e) {
  await patch({ etapa: 'conferir_dados', etapa_erro: null }).catch(() => {});
  throw e;
